// Reads the form post, cleans it, checks the config and builds the Monday search.
// Nothing is written here: static data is only read. "Remember Lead" writes it once Monday has the lead,
// and "Note Failed Try" when Monday refused it.
// This node must never throw. n8n would then answer the form with an empty 200, and the form would think it worked.
const store = $getWorkflowStaticData('global');
const DEDUPE_HOURS = 24;
const str = v => String(v ?? '').trim();

// ---- Config ----
const cfg = {
  board: str($env.MONDAY_BOARD_ID),
  group: str($env.MONDAY_GROUP_ID),
  newLabel: str($env.MONDAY_STATUS_NEW_LABEL) || 'New',
  country: (str($env.DEFAULT_COUNTRY) || 'US').toUpperCase(),
  col: {
    email: str($env.MONDAY_COL_EMAIL), phone: str($env.MONDAY_COL_PHONE), status: str($env.MONDAY_COL_STATUS),
    owner: str($env.MONDAY_COL_OWNER), message: str($env.MONDAY_COL_MESSAGE),
    company: str($env.MONDAY_COL_COMPANY), source: str($env.MONDAY_COL_SOURCE), lastInquiry: str($env.MONDAY_COL_LAST_INQUIRY),
  },
  owners: [],
};
const problems = [];
if (!str($env.MONDAY_API_TOKEN)) problems.push('MONDAY_API_TOKEN is empty');
if (!/^\d+$/.test(cfg.board)) problems.push('MONDAY_BOARD_ID must be the numeric board ID');
for (const [key, envName] of [['email', 'EMAIL'], ['phone', 'PHONE'], ['status', 'STATUS'], ['owner', 'OWNER'], ['message', 'MESSAGE']]) {
  if (!cfg.col[key]) problems.push(`MONDAY_COL_${envName} is empty`);
}
let owners = null;
try { owners = JSON.parse(str($env.OWNERS_JSON) || '[]'); } catch (e) { problems.push('OWNERS_JSON is not valid JSON'); }
if (owners && (!Array.isArray(owners) || !owners.length || owners.some(o => !o || !/^\d+$/.test(str(o.mondayUserId))))) {
  problems.push('OWNERS_JSON must be a list of owners, each with a numeric mondayUserId');
} else if (owners) {
  cfg.owners = owners.map(o => ({
    name: str(o.name) || `User ${o.mondayUserId}`, mondayUserId: str(o.mondayUserId),
    slackMemberId: str(o.slackMemberId), slackWebhookUrl: str(o.slackWebhookUrl), away: o.away === true,
  }));
}

// Calling codes for the countries this workflow can store in a Monday phone column.
const CALLING = { US: '1', CA: '1', GB: '44', IE: '353', AU: '61', NZ: '64', PH: '63', SG: '65', IN: '91', ZA: '27',
  AE: '971', DE: '49', FR: '33', ES: '34', IT: '39', NL: '31', MX: '52', BR: '55' };

// Turns what people type ("(202) 555-0101", "+44 7700 900123", "0044...") into E.164 ("+12025550101").
// Local numbers without a country code use the given country. Returns '' when it is not a usable number.
function toE164(raw, country) {
  let s = String(raw || '').trim().replace(/\s*(ext\.?|x|#)\s*\d+$/i, '');
  let digits = s.replace(/\D/g, '');
  if (!digits) return '';
  let e164;
  if (s.startsWith('+')) e164 = digits;
  else if (digits.startsWith('00')) e164 = digits.slice(2);
  else {
    const cc = CALLING[String(country || '').toUpperCase()];
    if (!cc) return '';
    if (cc === '1') {
      if (digits.length === 11 && digits.startsWith('1')) e164 = digits;
      else if (digits.length === 10) e164 = '1' + digits;
      else return '';
    } else {
      if (digits.startsWith('0')) digits = digits.slice(1); // national trunk prefix
      e164 = digits.startsWith(cc) && digits.length >= cc.length + 9 ? digits : cc + digits;
    }
  }
  if (e164.length < 8 || e164.length > 15 || e164.startsWith('0')) return '';
  if (e164.startsWith('1') && e164.length !== 11) return ''; // +1 numbers always have 10 digits after the 1
  return '+' + e164;
}

if (!CALLING[cfg.country]) problems.push(`DEFAULT_COUNTRY must be one of ${Object.keys(CALLING).join(', ')}`);

// Which country a +E.164 number belongs to, for the phone column's countryShortName. US and CA share +1,
// so the default country wins when it matches. Returns '' for countries not in the list above.
function countryOf(e164) {
  const d = e164.slice(1);
  if (CALLING[cfg.country] && d.startsWith(CALLING[cfg.country])) return cfg.country;
  for (const len of [3, 2, 1]) {
    const hit = Object.keys(CALLING).find(k => CALLING[k] === d.slice(0, len));
    if (hit) return hit;
  }
  return '';
}

// A short stable hash (cyrb53), used for the dedupe key and Monday's Idempotency-Key.
function hash(text) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < text.length; i++) {
    const ch = text.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
}

// ---- The form fields (common names from website forms are accepted) ----
const raw = $input.first().json.body;
const b = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
const field = (...keys) => {
  for (const k of keys) {
    const v = b[k];
    if (v !== undefined && v !== null && typeof v !== 'object' && str(v)) return String(v);
  }
  return '';
};
const tidy = (s, max) => String(s).replace(/\r\n?/g, '\n').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '')
  .replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim().slice(0, max);

const name = tidy(field('name', 'full_name', 'fullName') || `${field('first_name', 'firstName')} ${field('last_name', 'lastName')}`, 120);
const emailRaw = tidy(field('email', 'Email', 'email_address', 'emailAddress'), 254).replace(/\s/g, '');
const email = emailRaw.toLowerCase();
const phoneRaw = tidy(field('phone', 'Phone', 'phone_number', 'phoneNumber', 'tel'), 40);
const company = tidy(field('company', 'Company', 'company_name', 'business'), 120);
const message = tidy(field('message', 'Message', 'comments', 'details', 'inquiry'), 5000);
const source = tidy(field('source', 'form_name', 'formName', 'utm_source'), 80) || 'Website form';
const submissionId = tidy(field('submissionId', 'submission_id', 'entry_id', 'entryId', 'event_id'), 120);

const errors = [];
const EMAIL_RE = /^[^\s@<>()[\]\\,;:"']+@[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}$/;
const emailOk = Boolean(email) && EMAIL_RE.test(email) && !email.includes('..');
if (email && !emailOk) errors.push('email is not a valid address');
const phone = phoneRaw ? toE164(phoneRaw, cfg.country) : '';
if (phoneRaw && !phone) errors.push('phone is not a full phone number');
const phoneCountry = phone ? countryOf(phone) : '';
const valid = Boolean((emailOk ? email : '') || phone);
if (!valid && !email && !phoneRaw) errors.push('an email or a phone number is required');

const lead = {
  name, email: emailOk ? email : '', emailTyped: emailOk ? emailRaw : '', phone, phoneCountry, phoneInput: phoneRaw,
  phoneTyped: phone ? '' : phoneRaw, badEmail: emailOk ? '' : emailRaw, company, message, source, submissionId,
  itemName: (name || (emailOk ? email : '') || phone || 'Website lead').slice(0, 255),
  receivedAt: new Date().toISOString(),
};
// What the alert shows when the lead could not be saved, so it can be entered by hand.
const forAlert = Object.fromEntries(Object.entries({
  name, email: lead.email || lead.badEmail, phone: phoneRaw, company, source, submissionId, message,
}).filter(([, v]) => v));

// Same submission ID, or the same email, phone and message, within DEDUPE_HOURS counts as a repeat delivery.
const fingerprint = submissionId ? `sub:${submissionId}` : `msg:${lead.email}|${lead.phone}|${message.toLowerCase().replace(/\s+/g, ' ')}`;
const key = 'lead-' + hash(fingerprint);
const seen = (store.leads || {})[key];
const duplicate = Boolean(seen && Date.now() - Date.parse(seen.at) < DEDUPE_HOURS * 3600e3);
// Monday's Idempotency-Key is built from the submission, so a repeat delivery that arrives while the first one
// is still running gets Monday's first answer instead of a second item. "attempt" only changes after Monday has
// refused this submission with an answer, because Monday may keep that answer under the old key for 30 minutes.
const attempt = Number(((store.failed || {})[key] || {}).n) || 0;

// ---- The Monday search: one request, one items_page_by_column_values lookup per identifier ----
// Email: Monday matches the whole display text, so both the lowercase address and the address as typed are sent.
// Phone: Monday wants digits only and does a "contains" match, so "Match Lead" checks every hit exactly.
const defs = ['$board: ID!', '$cols: [String!]'];
const vars = { board: cfg.board, cols: [cfg.col.email, cfg.col.phone, cfg.col.status, cfg.col.owner, cfg.col.company].filter(Boolean) };
const parts = [];
const FIELDS = 'items { id name url created_at column_values(ids: $cols) { id text value } }';
if (lead.email) {
  defs.push('$emailCol: String!', '$emails: [String]!');
  Object.assign(vars, { emailCol: cfg.col.email, emails: [...new Set([lead.email, lead.emailTyped])] });
  parts.push(`by_email: items_page_by_column_values(board_id: $board, limit: 25, columns: [{column_id: $emailCol, column_values: $emails}]) { ${FIELDS} }`);
}
if (lead.phone) {
  const cc = CALLING[cfg.country];
  const digits = lead.phone.slice(1);
  // Numbers from the home country are searched without the country code, so items typed as "5552010101" match too.
  const needle = cc && phoneCountry === cfg.country && digits.startsWith(cc) ? digits.slice(cc.length) : digits;
  defs.push('$phoneCol: String!', '$phones: [String]!');
  Object.assign(vars, { phoneCol: cfg.col.phone, phones: [needle] });
  parts.push(`by_phone: items_page_by_column_values(board_id: $board, limit: 25, columns: [{column_id: $phoneCol, column_values: $phones}]) { ${FIELDS} }`);
}

return [{
  json: {
    configOk: !problems.length,
    error: problems.length ? `Config problem: ${problems.join('; ')}` : '',
    valid, errors, duplicate, duplicateOf: duplicate ? seen.itemId : '',
    key, attempt, cfg, lead, forAlert,
    request: parts.length ? { query: `query FindLead(${defs.join(', ')}) { ${parts.join(' ')} }`, variables: vars } : null,
  },
  pairedItem: { item: 0 },
}];

// Monday answers GraphQL errors with HTTP 200, so the body is checked here, not by the HTTP node.
// Phone hits come from a "contains" search, so every hit is normalised and compared exactly.
const res = $input.first().json;
const { cfg, lead } = $('Normalize Lead').first().json;
const describe = errs => errs.map(e => `${e.extensions?.code || 'error'}: ${e.message}`).join('; ').slice(0, 500);
if (Array.isArray(res.errors) && res.errors.length) {
  return [{ json: { ok: false, error: `Monday search failed: ${describe(res.errors)}` }, pairedItem: { item: 0 } }];
}
if (!res.data) return [{ json: { ok: false, error: 'Monday search returned no data' }, pairedItem: { item: 0 } }];

// Calling codes for the countries this workflow can store in a Monday phone column.
const CALLING = { US: '1', CA: '1', GB: '44', IE: '353', AU: '61', NZ: '64', PH: '63', SG: '65', IN: '91', ZA: '27',
  AE: '971', DE: '49', FR: '33', ES: '34', IT: '39', NL: '31', MX: '52', BR: '55' };

// Turns what people type ("(202) 555-0101", "+44 7700 900123", "0044...") into E.164 ("+12025550101").
// Local numbers without a country code use the given country. Returns '' when it is not a usable number.
function toE164(raw, country) {
  let s = String(raw || '').trim().replace(/\s*(ext\.?|x|#)\s*\d+$/i, '');
  let digits = s.replace(/\D/g, '');
  if (!digits) return '';
  let e164;
  if (s.startsWith('+')) e164 = digits;
  else if (digits.startsWith('00')) e164 = digits.slice(2);
  else {
    const cc = CALLING[String(country || '').toUpperCase()];
    if (!cc) return '';
    if (cc === '1') {
      if (digits.length === 11 && digits.startsWith('1')) e164 = digits;
      else if (digits.length === 10) e164 = '1' + digits;
      else return '';
    } else {
      if (digits.startsWith('0')) digits = digits.slice(1); // national trunk prefix
      e164 = digits.startsWith(cc) && digits.length >= cc.length + 9 ? digits : cc + digits;
    }
  }
  if (e164.length < 8 || e164.length > 15 || e164.startsWith('0')) return '';
  if (e164.startsWith('1') && e164.length !== 11) return ''; // +1 numbers always have 10 digits after the 1
  return '+' + e164;
}

const parse = s => { try { return s ? JSON.parse(s) : null; } catch (e) { return null; } };
const read = it => {
  const cv = Object.fromEntries((it.column_values || []).map(c => [c.id, c]));
  const emailV = parse(cv[cfg.col.email]?.value);
  const phoneV = parse(cv[cfg.col.phone]?.value);
  const ownerV = parse(cv[cfg.col.owner]?.value);
  return {
    id: String(it.id), name: it.name, url: it.url, createdAt: it.created_at || '',
    email: String(emailV?.email || '').trim().toLowerCase(), hasEmail: Boolean(emailV?.email),
    phone: phoneV?.phone ? toE164(phoneV.phone, phoneV.countryShortName || cfg.country) : '', hasPhone: Boolean(phoneV?.phone),
    status: cv[cfg.col.status]?.text || '',
    hasCompany: Boolean(cfg.col.company && cv[cfg.col.company]?.text),
    ownerIds: (ownerV?.personsAndTeams || []).filter(p => p.kind === 'person').map(p => String(p.id)),
    ownerText: cv[cfg.col.owner]?.text || '',
  };
};
const byEmail = (res.data.by_email?.items || []).map(read).filter(it => lead.email && it.email === lead.email);
const byPhone = (res.data.by_phone?.items || []).map(read).filter(it => lead.phone && it.phone === lead.phone);
// If the board already holds duplicates, the oldest item wins. Email is the stronger match.
const oldest = list => [...list].sort((a, b) => (Date.parse(a.createdAt) || 0) - (Date.parse(b.createdAt) || 0) || Number(a.id) - Number(b.id))[0];
const match = oldest(byEmail) || oldest(byPhone) || null;
const others = [...new Set([...byEmail, ...byPhone].map(i => i.id))].filter(id => id !== match?.id);

return [{
  json: {
    ok: true, found: Boolean(match), item: match,
    matchedBy: !match ? '' : byEmail.some(i => i.id === match.id) ? 'email' : 'phone',
    otherMatches: others,
    hits: { email: (res.data.by_email?.items || []).length, phone: (res.data.by_phone?.items || []).length },
  },
  pairedItem: { item: 0 },
}];

// The lead is already on the board: log the new inquiry as an update and refresh a few fields.
// It never touches the owner, the status, the name or the first message, and only fills contact details that are empty.
const { cfg, lead, key, attempt } = $('Normalize Lead').first().json;
const { item } = $input.first().json;
const html = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const now = lead.receivedAt;

const details = [
  ['Name', lead.name], ['Email', lead.email || lead.badEmail], ['Phone', lead.phone || lead.phoneTyped], ['Company', lead.company],
  ['Source', lead.source], ['Received', now.slice(0, 16).replace('T', ' ') + ' UTC'],
].filter(([, v]) => v);
// Update bodies are HTML, so everything the visitor typed is escaped.
const body = `<p><strong>New inquiry from the website:</strong> ${html(lead.message || '(no message)').replace(/\n/g, '<br>')}</p>`
  + `<p>${details.map(([k, v]) => `${k}: ${html(v)}`).join('<br>')}</p>`;

// Two separate field changes: "refresh" (last inquiry, source) always applies, "fill" adds contact details the
// item is missing. Monday checks phone numbers and emails itself, so if it refuses one, only "fill" fails.
const refresh = {};
if (cfg.col.lastInquiry) refresh[cfg.col.lastInquiry] = { date: now.slice(0, 10), time: now.slice(11, 19) };
if (cfg.col.source) refresh[cfg.col.source] = lead.source;
const fill = {};
if (lead.email && !item.hasEmail) fill[cfg.col.email] = { email: lead.email, text: lead.email };
if (lead.phone && lead.phoneCountry && !item.hasPhone) fill[cfg.col.phone] = { phone: lead.phone, countryShortName: lead.phoneCountry };
if (cfg.col.company && lead.company && !item.hasCompany) fill[cfg.col.company] = lead.company;

const defs = ['$item: ID!', '$body: String!'];
const variables = { item: item.id, body };
let fields = 'update: create_update(item_id: $item, body: $body) { id }';
if (Object.keys(refresh).length || Object.keys(fill).length) {
  defs.push('$board: ID!');
  variables.board = cfg.board;
}
if (Object.keys(refresh).length) {
  defs.push('$refresh: JSON!');
  variables.refresh = JSON.stringify(refresh); // column values go as a JSON string
  fields += ' refresh: change_multiple_column_values(board_id: $board, item_id: $item, column_values: $refresh) { id }';
}
if (Object.keys(fill).length) {
  defs.push('$fill: JSON!');
  variables.fill = JSON.stringify(fill);
  fields += ' fill: change_multiple_column_values(board_id: $board, item_id: $item, column_values: $fill) { id }';
}
return [{
  json: {
    request: { query: `mutation UpdateLead(${defs.join(', ')}) { ${fields} }`, variables },
    // Built from the submission: n8n's own retries and a repeat delivery that arrives meanwhile get the same key,
    // so Monday applies the update once and replays its answer.
    idempotencyKey: `${key}-a${attempt}-update`,
    refreshed: [...Object.keys(refresh), ...Object.keys(fill)],
  },
  pairedItem: { item: 0 },
}];

// create_update and the field changes run in one request, and Monday answers with partial data. If the update is
// saved, the inquiry is safe; a refused field change is passed on as a warning instead of failing the lead.
const res = $input.first().json;
const m = $('Match Lead').first().json;
const describe = errs => errs.map(e => `${e.extensions?.code || 'error'}: ${e.message}`).join('; ').slice(0, 500);
const errs = Array.isArray(res.errors) ? res.errors : [];
if (!res.data?.update?.id) {
  // refused: Monday answered, so the next try needs a new Idempotency-Key (see "Note Failed Try").
  return [{ json: { ok: false, refused: errs.length > 0, error: `Monday did not save the update: ${describe(errs) || 'no update id returned'}` }, pairedItem: { item: 0 } }];
}
const about = e => (e.path || [])[0] === 'fill' ? 'the missing contact details' : (e.path || [])[0] === 'refresh' ? 'the last inquiry and source' : 'some fields';
return [{
  json: {
    ok: true, status: 'updated', itemId: m.item.id, itemName: m.item.name, itemUrl: m.item.url,
    owner: null, ownerIds: m.item.ownerIds, ownerText: m.item.ownerText, matchedBy: m.matchedBy, otherMatches: m.otherMatches,
    updateId: String(res.data.update.id),
    warnings: errs.map(e => `Monday did not save ${about(e)}: ${describe([e])}`),
  },
  pairedItem: { item: 0 },
}];

// New lead: pick the next owner in OWNERS_JSON after the last one who got a lead, skipping anyone marked away.
// The pointer is only moved in "Remember Lead", after Monday has created the item.
const store = $getWorkflowStaticData('global');
const { cfg, lead, key, attempt } = $('Normalize Lead').first().json;
const owners = cfg.owners;
const start = owners.findIndex(o => o.mondayUserId === String(store.roundRobin?.lastOwnerId || ''));
let owner = null;
for (let step = 1; step <= owners.length && !owner; step++) {
  const o = owners[(start + step) % owners.length];
  if (!o.away) owner = o;
}

// Anything the visitor typed that could not go into its column is kept in the message.
const extra = [];
if (lead.badEmail) extra.push(`Email as typed: ${lead.badEmail}`);
if (lead.phoneTyped) extra.push(`Phone as typed: ${lead.phoneTyped}`);
if (lead.phone && !lead.phoneCountry) extra.push(`Phone: ${lead.phone}`);
const message = [lead.message, ...extra].filter(Boolean).join('\n\n');

// Column values are sent as one JSON string, in the format each column type expects.
const values = { [cfg.col.status]: { label: cfg.newLabel } };
if (lead.email) values[cfg.col.email] = { email: lead.email, text: lead.email };
if (lead.phone && lead.phoneCountry) values[cfg.col.phone] = { phone: lead.phone, countryShortName: lead.phoneCountry };
if (owner) values[cfg.col.owner] = { personsAndTeams: [{ id: Number(owner.mondayUserId), kind: 'person' }] };
if (message) values[cfg.col.message] = { text: message.slice(0, 2000) };
if (cfg.col.company && lead.company) values[cfg.col.company] = lead.company;
if (cfg.col.source) values[cfg.col.source] = lead.source;
if (cfg.col.lastInquiry) values[cfg.col.lastInquiry] = { date: lead.receivedAt.slice(0, 10), time: lead.receivedAt.slice(11, 19) };

// group_id is only sent when MONDAY_GROUP_ID is set; without it Monday uses the board's top group.
const query = cfg.group
  ? 'mutation CreateLead($board: ID!, $group: String!, $name: String!, $values: JSON!) { create_item(board_id: $board, group_id: $group, item_name: $name, column_values: $values) { id name url } }'
  : 'mutation CreateLead($board: ID!, $name: String!, $values: JSON!) { create_item(board_id: $board, item_name: $name, column_values: $values) { id name url } }';
const variables = { board: cfg.board, name: lead.itemName, values: JSON.stringify(values) };
if (cfg.group) variables.group = cfg.group;
return [{
  json: {
    owner, values, message,
    request: { query, variables },
    // Built from the submission: n8n's own retries, a repeat delivery that arrives meanwhile and the form's retry
    // after a lost answer all get the same key, so Monday creates one item and replays its answer.
    idempotencyKey: `${key}-a${attempt}-create`,
  },
  pairedItem: { item: 0 },
}];

// create_item either works completely or not at all (a bad column value fails the whole mutation).
// Monday checks phone numbers with Google's libphonenumber and checks emails itself, so a number that looks fine
// here (a typo, a made-up area code) can make Monday refuse the whole lead. In that case the lead is created again
// without that column, with the number or address kept in the message, instead of being lost.
const res = $input.first().json;
const pick = $('Pick Owner').first().json;
const { cfg, lead } = $('Normalize Lead').first().json;
const owner = pick.owner;
const describe = errs => errs.map(e => `${e.extensions?.code || 'error'}: ${e.message}`).join('; ').slice(0, 500);
const errs = Array.isArray(res.errors) ? res.errors : [];
const created = res.data?.create_item;
if (created?.id) {
  return [{
    json: {
      ok: true, retry: false, status: 'created', itemId: String(created.id), itemName: created.name, itemUrl: created.url,
      owner, ownerIds: owner ? [owner.mondayUserId] : [], ownerText: owner ? owner.name : '', matchedBy: '', otherMatches: [], warnings: [],
    },
    pairedItem: { item: 0 },
  }];
}

// Which contact column did Monday refuse? Its errors name the column type (PhoneColumn, EmailColumn).
const refusedContact = e => {
  if (e.extensions?.code !== 'ColumnValueException') return '';
  const d = e.extensions?.error_data || {};
  if (d.column_id && d.column_id === cfg.col.phone) return 'phone';
  if (d.column_id && d.column_id === cfg.col.email) return 'email';
  const type = String(d.column_type || '').toLowerCase();
  return type.includes('phone') ? 'phone' : type.includes('email') ? 'email' : '';
};
const kinds = errs.map(refusedContact);
const drop = [...new Set(kinds)].filter(k => k && pick.values[cfg.col[k]] !== undefined);
if (errs.length && drop.length && !kinds.includes('')) {
  const values = { ...pick.values };
  const notes = drop.map(k => k === 'phone'
    ? `Phone (Monday did not accept it): ${lead.phoneInput || lead.phone}`
    : `Email (Monday did not accept it): ${lead.email}`);
  for (const k of drop) delete values[cfg.col[k]];
  const noteText = notes.join('\n');
  const text = pick.message ? `${pick.message.slice(0, 2000 - noteText.length - 2)}\n\n${noteText}` : noteText;
  values[cfg.col.message] = { text: text.slice(0, 2000) };
  const what = drop.map(k => k === 'phone' ? `phone number ${lead.phoneInput || lead.phone}` : `email ${lead.email}`).join(' and the ');
  const them = drop.length > 1 ? 'them' : 'it';
  return [{
    json: {
      ok: false, retry: true, drop,
      warning: `Monday did not accept the ${what}, so the lead was saved without ${them}. You find ${them} in the message; please check with the lead.`,
      request: { query: pick.request.query, variables: { ...pick.request.variables, values: JSON.stringify(values) } },
      idempotencyKey: `${pick.idempotencyKey}-without-${drop.join('-')}`,
    },
    pairedItem: { item: 0 },
  }];
}
// refused: Monday answered, so the next try needs a new Idempotency-Key (see "Note Failed Try").
return [{ json: { ok: false, retry: false, refused: errs.length > 0, error: `Monday did not create the item: ${describe(errs) || 'no item id returned'}` }, pairedItem: { item: 0 } }];

// The second try, without the contact column Monday refused.
const res = $input.first().json;
const first = $('Check Create').first().json;
const { owner } = $('Pick Owner').first().json;
const describe = errs => errs.map(e => `${e.extensions?.code || 'error'}: ${e.message}`).join('; ').slice(0, 500);
const errs = Array.isArray(res.errors) ? res.errors : [];
const created = res.data?.create_item;
if (!created?.id) {
  return [{ json: { ok: false, refused: errs.length > 0, error: `Monday did not create the item, even without the ${first.drop.join(' and ')}: ${describe(errs) || 'no item id returned'}` }, pairedItem: { item: 0 } }];
}
return [{
  json: {
    ok: true, status: 'created', itemId: String(created.id), itemName: created.name, itemUrl: created.url,
    owner, ownerIds: owner ? [owner.mondayUserId] : [], ownerText: owner ? owner.name : '', matchedBy: '', otherMatches: [],
    warnings: [first.warning],
  },
  pairedItem: { item: 0 },
}];

// The form was told to retry. If Monday refused this lead with an answer (HTTP 200 with errors), Monday may keep
// that answer under the Idempotency-Key for 30 minutes, so the next try of the same submission must use a new key.
// Network errors, 5xx and 429 keep the key: Monday does not keep those, and if it did save the lead after all,
// the retry gets that same item back instead of a second one.
const store = $getWorkflowStaticData('global');
const items = $input.all();
const { key } = $('Normalize Lead').first().json;
if (items.some(it => it.json.refused === true)) {
  store.failed = store.failed || {};
  store.failed[key] = { n: ((store.failed[key] || {}).n || 0) + 1, at: new Date().toISOString() };
}
return items.map((it, i) => ({ json: it.json, pairedItem: { item: i } }));

// Monday has the lead, so this delivery is remembered (repeat deliveries are skipped for 24 hours)
// and, for a new item, the round robin pointer moves to the owner who got it.
const store = $getWorkflowStaticData('global');
const r = $input.first().json;
const { key } = $('Normalize Lead').first().json;
const now = new Date().toISOString();
const old = v => Date.now() - Date.parse(v.at) > 24 * 3600e3;
store.leads = store.leads || {};
for (const [k, v] of Object.entries(store.leads)) if (old(v)) delete store.leads[k];
store.leads[key] = { itemId: r.itemId, at: now };
if (store.failed) {
  delete store.failed[key];
  for (const [k, v] of Object.entries(store.failed)) if (old(v)) delete store.failed[k];
}
if (r.status === 'created' && r.owner) store.roundRobin = { lastOwnerId: r.owner.mondayUserId, at: now };
return [{ json: r, pairedItem: { item: 0 } }];

// The Slack message for the owner: their own webhook if OWNERS_JSON has one, otherwise the team channel with a mention.
const r = $input.first().json;
const { cfg, lead } = $('Normalize Lead').first().json;
const team = String($env.SLACK_WEBHOOK_URL || '').trim();
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); // visitor text cannot ping @channel
const owner = r.owner || cfg.owners.find(o => (r.ownerIds || []).includes(o.mondayUserId)) || null;
const who = owner ? (owner.slackMemberId ? `<@${owner.slackMemberId}>` : esc(owner.name)) : '';
const label = esc(lead.name || lead.email || lead.phone);

let headline;
if (r.status === 'created') {
  headline = owner ? `${who} New lead for you: *${label}*`
    : `*New lead with no owner:* *${label}*. Everyone in OWNERS_JSON is marked away, so please assign it by hand.`;
} else {
  headline = owner ? `${who} Returning lead: *${label}* sent a new inquiry (matched by ${r.matchedBy}).`
    : `*Returning lead:* *${label}* sent a new inquiry (matched by ${r.matchedBy}). Owner on the item: ${esc(r.ownerText) || 'nobody'}.`;
}
const lines = [headline];
if (lead.company) lines.push(`Company: ${esc(lead.company)}`);
if (lead.email) lines.push(`Email: ${esc(lead.email)}`);
if (lead.phone || lead.phoneTyped) lines.push(`Phone: ${esc(lead.phone || lead.phoneTyped)}`);
lines.push(`Source: ${esc(lead.source)}`);
if (lead.message) lines.push(`Message: ${esc(lead.message.length > 500 ? lead.message.slice(0, 500) + '...' : lead.message)}`);
if (r.otherMatches?.length) lines.push(`Heads up: ${r.otherMatches.length} more item(s) on the board have this email or phone.`);
for (const w of r.warnings || []) lines.push(esc(w));
lines.push(`<${r.itemUrl}|Open in Monday>`);

const webhookUrl = owner?.slackWebhookUrl || team;
if (!webhookUrl) return []; // no Slack configured: the lead is saved, nothing else to do
return [{ json: { webhookUrl, text: lines.join('\n'), itemId: r.itemId }, pairedItem: { item: 0 } }];

// Both triggers start here: the 30 minute schedule and the protected Run Now webhook.
const str = v => String(v ?? '').trim();
const problems = [];
let owners = null;
try { owners = JSON.parse(str($env.OWNERS_JSON) || '[]'); } catch (e) { problems.push('OWNERS_JSON is not valid JSON'); }
if (!Array.isArray(owners)) { owners = []; problems.push('OWNERS_JSON must be a list'); }
const cfg = {
  board: str($env.MONDAY_BOARD_ID),
  newLabel: str($env.MONDAY_STATUS_NEW_LABEL) || 'New',
  slaHours: Number($env.SLA_HOURS) > 0 ? Number($env.SLA_HOURS) : 2,
  col: { status: str($env.MONDAY_COL_STATUS), owner: str($env.MONDAY_COL_OWNER) },
  owners: owners.filter(o => o && str(o.mondayUserId)).map(o => ({
    name: str(o.name) || `User ${o.mondayUserId}`, mondayUserId: str(o.mondayUserId),
    slackMemberId: str(o.slackMemberId), slackWebhookUrl: str(o.slackWebhookUrl), away: o.away === true,
  })),
  team: str($env.SLACK_WEBHOOK_URL),
  managerId: str($env.MANAGER_SLACK_ID),
  managerHook: str($env.MANAGER_SLACK_WEBHOOK_URL) || str($env.SLACK_WEBHOOK_URL),
  pageSize: 100,
  maxPages: 50,
};
if (!str($env.MONDAY_API_TOKEN)) problems.push('MONDAY_API_TOKEN is empty');
if (!/^\d+$/.test(cfg.board)) problems.push('MONDAY_BOARD_ID must be the numeric board ID');
if (!cfg.col.status || !cfg.col.owner) problems.push('MONDAY_COL_STATUS and MONDAY_COL_OWNER are required');
if (!cfg.team) problems.push('SLACK_WEBHOOK_URL is required for SLA alerts');
// Nobody is waiting on a reply here, so a config problem simply fails the run and the error workflow reports it.
// (n8n cuts a thrown message at ": ", so the message avoids that pattern.)
if (problems.length) throw new Error(`SLA check config problem. ${problems.join('; ')}`);

return [{
  json: {
    cfg, page: 0, items: [],
    request: {
      query: 'query NewLeads($board: ID!, $statusCol: String!, $labels: [String]!, $cols: [String!], $limit: Int!) { items_page_by_column_values(board_id: $board, limit: $limit, columns: [{column_id: $statusCol, column_values: $labels}]) { cursor items { id name url created_at column_values(ids: $cols) { id text value } } } }',
      variables: { board: cfg.board, statusCol: cfg.col.status, labels: [cfg.newLabel], cols: [cfg.col.status, cfg.col.owner], limit: cfg.pageSize },
    },
  },
  pairedItem: { item: 0 },
}];

// Adds this page of New items to the list and prepares the next page. The HTTP node's output replaces $json,
// so the list so far comes from the last "More Pages?" run (or from "Start SLA Check" on the first page).
const res = $input.first().json;
const prev = $('More Pages?').isExecuted ? $('More Pages?').first().json : $('Start SLA Check').first().json;
const { cfg } = prev;
// n8n cuts a thrown message at ": ", so these messages avoid that pattern.
const describe = errs => errs.map(e => `${e.extensions?.code || 'error'} (${String(e.message).replace(/:\s/g, ' - ')})`).join('; ').slice(0, 500);
// GraphQL errors arrive with HTTP 200. Failing here ends the run and the error workflow reports it.
if (Array.isArray(res.errors) && res.errors.length) throw new Error(`Monday refused the SLA query. ${describe(res.errors)}. No reminders were sent; the next run tries again.`);
const page = res.data?.items_page_by_column_values || res.data?.next_items_page;
if (!page || !Array.isArray(page.items)) throw new Error(`Monday sent an unexpected SLA response. ${JSON.stringify(res).slice(0, 300).replace(/:\s/g, ' - ')}`);

const parse = s => { try { return s ? JSON.parse(s) : null; } catch (e) { return null; } };
const slim = it => {
  const cv = Object.fromEntries((it.column_values || []).map(c => [c.id, c]));
  const ownerV = parse(cv[cfg.col.owner]?.value);
  return {
    id: String(it.id), name: it.name, url: it.url, createdAt: it.created_at || '', status: cv[cfg.col.status]?.text || '',
    ownerIds: (ownerV?.personsAndTeams || []).filter(p => p.kind === 'person').map(p => String(p.id)),
    ownerText: cv[cfg.col.owner]?.text || '',
  };
};
const pageNo = prev.page + 1;
const more = Boolean(page.cursor) && pageNo < cfg.maxPages;
return [{
  json: {
    cfg, page: pageNo, items: [...prev.items, ...page.items.map(slim)], more, complete: !page.cursor,
    request: more ? {
      query: 'query NextLeads($cursor: String!, $limit: Int!, $cols: [String!]) { next_items_page(cursor: $cursor, limit: $limit) { cursor items { id name url created_at column_values(ids: $cols) { id text value } } } }',
      variables: { cursor: page.cursor, limit: cfg.pageSize, cols: [cfg.col.status, cfg.col.owner] },
    } : null,
  },
  pairedItem: { item: 0 },
}];

// Decides who to remind. After SLA_HOURS the owner gets one nudge; after twice SLA_HOURS the manager gets one
// escalation. Static data remembers what was sent, so a lead is never nudged or escalated twice.
// One message per person, listing all of their leads, keeps Slack quiet and inside its rate limit.
const store = $getWorkflowStaticData('global');
const { cfg, items, complete } = $input.first().json;
const H = 3600e3, now = Date.now(), sla = cfg.slaHours;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const hours = ms => (ms / H).toFixed(1);
store.sla = store.sla || {};

const live = new Map();
for (const it of items) if (it.status === cfg.newLabel) live.set(it.id, it); // double-check the label, drop repeats
// Leads that left "New" are forgotten (only when the full list was read).
if (complete) for (const id of Object.keys(store.sla)) if (!live.has(id)) delete store.sla[id];

const groups = new Map();
const add = (key, base, id, line) => {
  if (!groups.has(key)) groups.set(key, { ...base, itemIds: [], lines: [] });
  groups.get(key).itemIds.push(id);
  groups.get(key).lines.push(line);
};
for (const it of live.values()) {
  const age = now - Date.parse(it.createdAt);
  if (!(age >= sla * H)) continue; // also skips items without a readable creation time
  const rec = store.sla[it.id] || {};
  const owner = cfg.owners.find(o => it.ownerIds.includes(o.mondayUserId)) || null;
  const ownerLabel = !owner ? esc(it.ownerText) || 'nobody'
    : owner.away ? `${esc(owner.name)} (away)` : owner.slackMemberId ? `<@${owner.slackMemberId}>` : esc(owner.name);
  const link = `<${it.url}|${esc(it.name)}>`;
  if (age >= 2 * sla * H) {
    if (!rec.escalatedAt) add('manager', { kind: 'escalate', webhookUrl: cfg.managerHook }, it.id, `${link}, owner ${ownerLabel}, waiting ${hours(age)} h`);
  } else if (!rec.nudgedAt) {
    // Nudge the owner directly. Without an owner who can act (none, not in OWNERS_JSON, or away), ask the team channel.
    if (owner && !owner.away) add(`owner:${owner.mondayUserId}`, { kind: 'nudge', webhookUrl: owner.slackWebhookUrl || cfg.team, mention: ownerLabel }, it.id, `${link}, waiting ${hours(age)} h`);
    else add('team', { kind: 'nudge', webhookUrl: cfg.team, mention: '' }, it.id, `${link}, owner ${ownerLabel}, waiting ${hours(age)} h`);
  }
}

const out = [];
for (const [key, g] of groups) {
  const n = g.lines.length;
  let head;
  if (g.kind === 'escalate') {
    head = `${cfg.managerId ? `<@${cfg.managerId}> ` : ''}*SLA missed:* ${n === 1 ? '1 lead is' : `${n} leads are`} still New after more than ${2 * sla} h.`;
  } else if (key === 'team') {
    head = `*${n === 1 ? '1 lead needs' : `${n} leads need`} an owner.* Still New after more than ${sla} h, and the owner is missing, not in OWNERS_JSON or away:`;
  } else {
    head = `${g.mention} ${n === 1 ? 'This lead is' : `These ${n} leads are`} still New after more than ${sla} h. Please reach out:`;
  }
  out.push({ json: { kind: g.kind, webhookUrl: g.webhookUrl, itemIds: g.itemIds, text: [head, ...g.lines.map(l => `- ${l}`)].join('\n') }, pairedItem: { item: 0 } });
}
return out; // nothing overdue: the run ends here

// Slack accepted this alert, so its leads are remembered. A refused alert skips this node and is sent
// again on the next run.
const store = $getWorkflowStaticData('global');
store.sla = store.sla || {};
const alert = $('Each Alert').itemMatching(0).json;
const now = new Date().toISOString();
for (const id of alert.itemIds) {
  const rec = store.sla[id] || (store.sla[id] = {});
  if (alert.kind === 'escalate') { rec.escalatedAt = now; rec.nudgedAt = rec.nudgedAt || now; }
  else rec.nudgedAt = now;
}
return [{ json: { sent: true, kind: alert.kind, itemIds: alert.itemIds }, pairedItem: { item: 0 } }];
